const $=id=>document.getElementById(id);
const pool=[['🧸','小熊'],['🍎','蘋果'],['📘','書本'],['⚽','足球'],['🎁','禮物盒'],['🚗','玩具車'],['🥕','紅蘿蔔'],['🍐','梨子'],['🧱','積木'],['🍊','橘子']];
let items=[],left=null,right=null,side='left',order=[],records=[],done=false;
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function newRound(){const n=$('count').value==='random'?3+Math.floor(Math.random()*2):Number($('count').value);const weights=shuffle(Array.from({length:n},(_,i)=>i+1));items=shuffle([...pool]).slice(0,n).map(([icon,name],i)=>({icon,name,weight:weights[i]}));left=null;right=null;side='left';order=[];records=[];done=false;$('feedback').textContent='先用天平比較，再試著排一排。';$('feedback').className='';render();}
function objectButton(i,action){const b=document.createElement('button');b.innerHTML=`<span class="emoji" aria-hidden="true">${items[i].icon}</span>${items[i].name}`;b.onclick=()=>action(i);return b;}
function place(i){if(side==='left'){if(right===i)right=null;left=i;side='right';}else{if(left===i)left=null;right=i;side='left';}if(left!==null&&right!==null){const heavy=items[left].weight>items[right].weight?left:right,light=heavy===left?right:left;if(!records.some(r=>r.heavy===heavy&&r.light===light))records.push({heavy,light});}render();}
function render(){const objects=$('objects');objects.replaceChildren();items.forEach((it,i)=>{const b=objectButton(i,place);b.className='object';b.setAttribute('aria-label',`${it.name}，${left===i?'在左邊':right===i?'在右邊':'點選放到'+(side==='left'?'左':'右')+'邊'}`);const small=document.createElement('small');small.textContent=left===i?'在左邊':right===i?'在右邊':'點我放'+(side==='left'?'左':'右')+'邊';b.append(small);objects.append(b);});$('select-left').setAttribute('aria-pressed',side==='left');$('select-right').setAttribute('aria-pressed',side==='right');for(const [which,index]of [['left',left],['right',right]]){$(which+'-icon').textContent=index===null?'':items[index].icon;$(which+'-name').textContent=index===null?(which==='left'?'左':'右')+'邊空空的':items[index].name;}
let tilt=0;if(left!==null&&right!==null){tilt=items[left].weight>items[right].weight?-10:10;const heavy=tilt<0?left:right,light=heavy===left?right:left;$('result').textContent=`${items[heavy].name}比較重，${items[light].name}比較輕。`;}else $('result').textContent='選兩個物品，看看哪邊會往下沉。';$('beam').style.transform=`rotate(${tilt}deg)`;for(const [id,x]of [['left-pan',155],['right-pan',565]])$(id).style.transform=`rotate(${-tilt}deg)`,$(id).style.transformOrigin=`${x}px 100px`;$('balance').setAttribute('aria-label','天平：'+$('result').textContent);$('records').replaceChildren();if(!records.length){const li=document.createElement('li');li.textContent='還沒有紀錄，先做一次實驗吧！';$('records').append(li);}else records.forEach(r=>{const li=document.createElement('li');li.textContent=`${items[r.heavy].icon} ${items[r.heavy].name} 比 ${items[r.light].icon} ${items[r.light].name} 重`;$('records').append(li);});$('record-count').textContent=records.length+' 組比較';renderOrder();}
function editOrder(){done=false;$('feedback').textContent='排好了嗎？按「檢查答案」看看。';$('feedback').className='';renderOrder();}
function renderOrder(){$('order').style.gridTemplateColumns=`repeat(${items.length},1fr)`;$('order').replaceChildren();for(let pos=0;pos<items.length;pos++){const slot=document.createElement('div');slot.className='slot';if(pos<order.length){const i=order[pos],b=objectButton(i,()=>{order.splice(pos,1);editOrder();});b.setAttribute('aria-label',`第 ${pos+1} 個：${items[i].name}，點選移回待選區`);slot.append(b);}else slot.textContent=pos+1;$('order').append(slot);}$('choices').replaceChildren();items.forEach((it,i)=>{if(!order.includes(i))$('choices').append(objectButton(i,()=>{order.push(i);editOrder();}));});$('check').disabled=order.length!==items.length||done;}
$('select-left').onclick=()=>{side='left';render();};$('select-right').onclick=()=>{side='right';render();};$('clear').onclick=()=>{left=right=null;side='left';render();};$('retry').onclick=()=>{order=[];editOrder();};$('check').onclick=()=>{if(order.length!==items.length)return;const correct=order.every((i,p)=>p===0||items[order[p-1]].weight<items[i].weight);$('feedback').textContent=correct?'答對了！你用實驗找出了由輕到重的順序！🎉':'還差一點！再用天平比一比相鄰的兩個物品，調整後再試一次。';$('feedback').className=correct?'success':'try';done=correct;renderOrder();};$('new').onclick=newRound;$('count').onchange=newRound;newRound();
